/**
 * Signs release builds with our own key instead of the debug key.
 *
 * android/ is generated by `expo prebuild` (and gitignored), so this edits
 * the generated app/build.gradle every time instead of by hand. The key
 * itself never enters the repo; Gradle reads these properties from
 * ~/.gradle/gradle.properties locally, or from ORG_GRADLE_PROJECT_<name>
 * environment variables in CI:
 *
 *   GEN3_UPLOAD_STORE_FILE      absolute path to the .jks keystore
 *   GEN3_UPLOAD_STORE_PASSWORD
 *   GEN3_UPLOAD_KEY_ALIAS
 *   GEN3_UPLOAD_KEY_PASSWORD
 *
 * Without them, release builds fall back to the debug key (fine for trying
 * a build; such an APK can't be updated by one signed with the real key).
 */
const { withAppBuildGradle } = require("expo/config-plugins");

const RELEASE_CONFIG = `
        release {
            if (findProperty('GEN3_UPLOAD_STORE_FILE')) {
                storeFile file(findProperty('GEN3_UPLOAD_STORE_FILE'))
                storePassword findProperty('GEN3_UPLOAD_STORE_PASSWORD')
                keyAlias findProperty('GEN3_UPLOAD_KEY_ALIAS')
                keyPassword findProperty('GEN3_UPLOAD_KEY_PASSWORD')
            }
        }`;

/** Replaces `search` once; throws if the template changed and it's gone. */
function replaceOnce(src, search, replacement) {
  if (!src.includes(search))
    throw new Error(
      `with-release-signing: "${search.trim()}" not found in app/build.gradle`,
    );
  return src.replace(search, replacement);
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    let src = mod.modResults.contents;
    if (src.includes("GEN3_UPLOAD_STORE_FILE")) return mod; // already applied
    src = replaceOnce(
      src,
      "    signingConfigs {",
      `    signingConfigs {${RELEASE_CONFIG}`,
    );
    // The second `signingConfig signingConfigs.debug` is the release build type's.
    const release = src.indexOf("        release {", src.indexOf("buildTypes"));
    if (release === -1)
      throw new Error("with-release-signing: release build type not found");
    src =
      src.slice(0, release) +
      replaceOnce(
        src.slice(release),
        "signingConfig signingConfigs.debug",
        "signingConfig findProperty('GEN3_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
      );
    mod.modResults.contents = src;
    return mod;
  });
};
